query clusters($q: String, $predicate: Predicate, $size: Int = 20, $from: Int = 0, $checklistKey: ID){
  occurrenceSearch(q: $q, predicate: $predicate, size: $size, from: $from) {
    documents(size: $size, from: $from) {
      total
      results {
        key
        basisOfRecord
        catalogNumber
        publishingOrgKey
        publisherTitle
        stillImageCount
        primaryImage {
          identifier
        }
        datasetKey
        datasetTitle
        typeStatus
        classification(checklistKey: $checklistKey) {
          acceptedUsage {
            key
          }
        }
        volatile {
          features {
            isSequenced
            isTreament
          }
        }
        related(size: 10) {
          count
          size
          from
          relatedOccurrences {
            reasons
            stub {
              gbifId
            }
            occurrence {
              key
              basisOfRecord
              catalogNumber
              publishingOrgKey
              publisherTitle
              stillImageCount
              primaryImage {
                identifier
              }
              datasetKey
              datasetTitle
              typeStatus
              classification(checklistKey: $checklistKey) {
                acceptedUsage {
                  key
                }
              }
              volatile {
                features {
                  isSequenced
                  isTreament
                }
              }
              related(size: 8) {
								count
                relatedOccurrences {
                  reasons
                  stub {
                    gbifId
                  }
                  occurrence {
                    key
                    basisOfRecord
                    catalogNumber
                    publishingOrgKey
                    publisherTitle
                    stillImageCount
                    primaryImage {
                      identifier
                    }
                    datasetKey
                    datasetTitle
                    typeStatus
                    classification(checklistKey: $checklistKey) {
                      acceptedUsage {
                        key
                      }
                    }
                    volatile {
                      features {
                        isSequenced
                        isTreament
                      }
                    }
                    related(size: 5) {
                      count
                      relatedOccurrences {
                        stub {
                          gbifId
                        }
                        reasons
                        occurrence {
                          key
                          basisOfRecord
                          catalogNumber
                          publishingOrgKey
                          publisherTitle
                          stillImageCount
                          primaryImage {
                            identifier
                          }
                          datasetKey
                          datasetTitle
                          typeStatus
                          classification(checklistKey: $checklistKey) {
                            acceptedUsage {
                              key
                            }
                          }
                          volatile {
                            features {
                              isSequenced
                              isTreament
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
